ITEMS.append({
 "id": "l7-ann-aerodromio", "title": "Αλλαγή πύλης στο αεροδρόμιο", "title_en": "A gate change at the airport", "type": "announcement", "level": "B2",
 "context_el": "Θα ακούσετε μια ανακοίνωση στο αεροδρόμιο.",
 "script": [
  L("Εκφωνήτρια", "f", "Προσοχή παρακαλώ. Οι επιβάτες της πτήσης προς Ηράκλειο, που ήταν προγραμματισμένη να αναχωρήσει στις οκτώ και δέκα, παρακαλούνται να μεταβούν στην πύλη Β δεκαοκτώ αντί για την πύλη Α τέσσερα.", "Attention please. Passengers on the flight to Heraklion, which was scheduled to depart at ten past eight, are requested to go to gate B18 instead of gate A4."),
  L("Εκφωνήτρια", "f", "Λόγω καθυστέρησης στην άφιξη του αεροσκάφους, η νέα ώρα αναχώρησης είναι οκτώ και πενήντα. Η επιβίβαση θα ξεκινήσει είκοσι λεπτά νωρίτερα.", "Owing to the late arrival of the aircraft, the new departure time is ten to nine. Boarding will begin twenty minutes earlier."),
  L("Εκφωνήτρια", "f", "Υπενθυμίζεται ότι επιτρέπεται μία χειραποσκευή ανά επιβάτη, και μία μικρή τσάντα που χωράει κάτω από το κάθισμα. Οι επιβάτες με παιδιά ή με ειδικές ανάγκες θα επιβιβαστούν πρώτοι.", "Please remember that one piece of hand luggage is allowed per passenger, plus one small bag that fits under the seat. Passengers with children or with special needs will board first."),
 ],
 "questions": [
  Q("Τι αλλάζει για την πτήση προς Ηράκλειο;", ["Η πύλη και η ώρα αναχώρησης", "Μόνο ο προορισμός", "Η πτήση ακυρώνεται", "Η εταιρεία που την εκτελεί"], 0, "παρακαλούνται να μεταβούν στην πύλη Β δεκαοκτώ ... η νέα ώρα αναχώρησης είναι οκτώ και πενήντα"),
  Q("Πότε θα ξεκινήσει η επιβίβαση;", ["Στις 8:10", "Στις 8:30", "Στις 8:50", "Στις 9:10"], 1, "Η επιβίβαση θα ξεκινήσει είκοσι λεπτά νωρίτερα [από τις 8:50]."),
  Q("Ποιοι θα μπουν πρώτοι στο αεροπλάνο;", ["Όσοι έχουν μόνο χειραποσκευή", "Οι επιβάτες της πρώτης θέσης", "Οι οικογένειες με παιδιά και τα άτομα με ειδικές ανάγκες", "Όσοι κάθονται στο πίσω μέρος"], 2, "Οι επιβάτες με παιδιά ή με ειδικές ανάγκες θα επιβιβαστούν πρώτοι."),
 ],
 "gloss": {"πτήσης": "πτήση — flight", "προγραμματισμένη": "προγραμματισμένος — scheduled", "μεταβούν": "μεταβαίνω — to go, proceed", "πύλη": "πύλη — gate", "αεροσκάφους": "αεροσκάφος — aircraft", "επιβίβαση": "επιβίβαση — boarding", "χειραποσκευή": "χειραποσκευή — hand luggage", "ειδικές ανάγκες": "άτομα με ειδικές ανάγκες — people with disabilities"},
})

ITEMS.append({
 "id": "l7-vm-synavlia", "title": "Τα εισιτήρια της συναυλίας", "title_en": "The concert tickets", "type": "voicemail", "level": "B2",
 "context_el": "Θα ακούσετε ένα μήνυμα που άφησε η Ρένα στον τηλεφωνητή του φίλου της, του Παύλου.",
 "script": [
  L("Ρένα", "f", "Παύλο, γεια, η Ρένα είμαι. Άκου, έχω ένα νέο που δεν θα σου αρέσει: η συναυλία του Σαββάτου αναβλήθηκε, γιατί ο τραγουδιστής αρρώστησε. Το έγραψαν σήμερα το πρωί στη σελίδα του θεάτρου.", "Pavlos, hi, it's Rena. Listen, I have some news you won't like: Saturday's concert has been postponed because the singer is ill. They posted it on the theatre's page this morning."),
  L("Ρένα", "f", "Η καλή είδηση είναι ότι τα εισιτήρια ισχύουν για τη νέα ημερομηνία, που είναι η τελευταία Παρασκευή του μήνα. Αν δεν μπορούμε τότε, μας επιστρέφουν τα χρήματα, αλλά πρέπει να το δηλώσουμε μέσα σε δέκα μέρες.", "The good news is that the tickets are valid for the new date, which is the last Friday of the month. If we can't make it then, they'll refund the money, but we have to say so within ten days."),
  L("Ρένα", "f", "Εγώ εκείνη την Παρασκευή έχω βάρδια μέχρι τις οκτώ, αλλά νομίζω ότι προλαβαίνω, αφού αρχίζει στις εννιά και μισή. Πες μου εσύ αν σε βολεύει, για να ξέρω τι να κάνω με τα εισιτήρια. Α, και το Σάββατο, αφού μείναμε χωρίς πρόγραμμα, πάμε για φαγητό;", "That Friday I'm on shift until eight, but I think I'll make it, since it starts at half past nine. Let me know if it suits you, so I know what to do with the tickets. Oh, and on Saturday, since we're left without plans, shall we go out to eat?"),
 ],
 "questions": [
  Q("Τι έγινε με τη συναυλία;", ["Ακυρώθηκε οριστικά", "Αναβλήθηκε λόγω ασθένειας του τραγουδιστή", "Μεταφέρθηκε σε άλλο θέατρο", "Έγινε νωρίτερα"], 1, "η συναυλία του Σαββάτου αναβλήθηκε, γιατί ο τραγουδιστής αρρώστησε"),
  Q("Τι ισχύει για τα εισιτήρια;", ["Πρέπει να αγοράσουν καινούργια", "Ισχύουν για τη νέα ημερομηνία ή επιστρέφονται τα χρήματα, αν το ζητήσουν εγκαίρως", "Επιστρέφονται αυτόματα τα χρήματα", "Ισχύουν μόνο για το Σάββατο"], 1, "τα εισιτήρια ισχύουν για τη νέα ημερομηνία ... μας επιστρέφουν τα χρήματα, αλλά πρέπει να το δηλώσουμε μέσα σε δέκα μέρες"),
  Q("Τι προτείνει η Ρένα για το Σάββατο;", ["Να πάνε σε άλλη συναυλία", "Να μείνουν σπίτι", "Να βγουν για φαγητό", "Να πάνε στο θέατρο να ζητήσουν εξηγήσεις"], 2, "το Σάββατο, αφού μείναμε χωρίς πρόγραμμα, πάμε για φαγητό;"),
 ],
 "gloss": {"αναβλήθηκε": "αναβάλλομαι — to be postponed", "ισχύουν": "ισχύω — to be valid", "να το δηλώσουμε": "δηλώνω — to declare, notify", "βάρδια": "βάρδια — shift", "προλαβαίνω": "προλαβαίνω — to make it in time", "σε βολεύει": "με βολεύει — it suits me"},
})

ITEMS.append({
 "id": "l7-dia-ypnos", "title": "Δεν με παίρνει ο ύπνος", "title_en": "I can't get to sleep", "type": "dialogue", "level": "B2",
 "context_el": "Θα ακούσετε μια συζήτηση ανάμεσα σε έναν ασθενή, τον κύριο Λαμπρόπουλο, και την παθολόγο του.",
 "script": [
  L("Γιατρός", "f", "Λοιπόν, κύριε Λαμπρόπουλε, τι σας φέρνει σήμερα;", "Well, Mr Lambropoulos, what brings you here today?"),
  L("Κύριος Λαμπρόπουλος", "m", "Γιατρέ μου, εδώ και δύο μήνες δεν μπορώ να κοιμηθώ. Ξαπλώνω κατά τις έντεκα, αλλά στριφογυρίζω μέχρι τις δύο. Και ξυπνάω στις έξι, χωρίς ξυπνητήρι, κουρασμένος.", "Doctor, for two months now I haven't been able to sleep. I lie down around eleven, but I toss and turn until two. And I wake up at six, without an alarm, tired."),
  L("Γιατρός", "f", "Άλλαξε κάτι στη ζωή σας τότε; Στη δουλειά, στην οικογένεια;", "Did something change in your life at that time? At work, in the family?"),
  L("Κύριος Λαμπρόπουλος", "m", "Μας άλλαξαν τον προϊστάμενο και έχει πολύ περισσότερη πίεση. Φέρνω και δουλειά στο σπίτι, απαντάω σε email μέχρι αργά από το κινητό.", "They changed our manager and there's much more pressure. I bring work home too, and answer emails until late on my phone."),
  L("Γιατρός", "f", "Αυτό εξηγεί πολλά. Η οθόνη λίγο πριν τον ύπνο κρατάει τον εγκέφαλο σε εγρήγορση. Πόσους καφέδες πίνετε;", "That explains a lot. A screen just before sleep keeps the brain alert. How many coffees do you drink?"),
  L("Κύριος Λαμπρόπουλος", "m", "Τρεις, τέσσερις… ο τελευταίος γύρω στις έξι το απόγευμα, για να αντέξω μέχρι το βράδυ.", "Three, four… the last one around six in the evening, to keep going until the evening."),
  L("Γιατρός", "f", "Θα σας ζητήσω να δοκιμάσετε κάποια πράγματα για τρεις εβδομάδες, πριν σκεφτούμε φάρμακα. Τελευταίος καφές μέχρι τις δύο το μεσημέρι. Το κινητό εκτός κρεβατοκάμαρας μία ώρα πριν κοιμηθείτε. Και λίγο περπάτημα κάθε μέρα. Αν δεν δούμε βελτίωση, θα κάνουμε και κάποιες εξετάσεις.", "I'll ask you to try a few things for three weeks before we think about medication. Last coffee by two in the afternoon. The phone out of the bedroom an hour before you go to sleep. And a little walking every day. If we see no improvement, we'll also do some tests."),
 ],
 "questions": [
  Q("Ποιο είναι το πρόβλημα του ασθενούς;", ["Κοιμάται πάρα πολλές ώρες", "Αργεί πολύ να κοιμηθεί και ξυπνάει νωρίς κουρασμένος", "Ξυπνάει πολλές φορές από θόρυβο", "Έχει πονοκεφάλους το πρωί"], 1, "στριφογυρίζω μέχρι τις δύο. Και ξυπνάω στις έξι, χωρίς ξυπνητήρι, κουρασμένος"),
  Q("Τι άλλαξε στη ζωή του πριν από δύο μήνες;", ["Μετακόμισε", "Απέκτησε παιδί", "Ήρθε νέος προϊστάμενος και αυξήθηκε η πίεση στη δουλειά", "Άλλαξε δουλειά"], 2, "Μας άλλαξαν τον προϊστάμενο και έχει πολύ περισσότερη πίεση."),
  Q("Γιατί η γιατρός ρωτάει για τον καφέ;", ["Γιατί ο καφές αργά το απόγευμα μπορεί να εμποδίζει τον ύπνο", "Γιατί ο ασθενής έχει πρόβλημα στο στομάχι", "Γιατί θέλει να του συστήσει περισσότερο καφέ", "Γιατί ο καφές δεν ταιριάζει με τα φάρμακά του"], 0, "Τελευταίος καφές μέχρι τις δύο το μεσημέρι."),
  Q("Τι αποφασίζει τελικά η γιατρός;", ["Να του γράψει αμέσως υπνωτικά", "Να τον στείλει σε ψυχολόγο", "Να του δώσει άδεια από τη δουλειά", "Να δοκιμάσει πρώτα αλλαγές στις συνήθειές του για τρεις εβδομάδες"], 3, "Θα σας ζητήσω να δοκιμάσετε κάποια πράγματα για τρεις εβδομάδες, πριν σκεφτούμε φάρμακα."),
 ],
 "gloss": {"παθολόγο": "παθολόγος — GP, internist", "στριφογυρίζω": "στριφογυρίζω — to toss and turn", "ξυπνητήρι": "ξυπνητήρι — alarm clock", "προϊστάμενο": "προϊστάμενος — manager, boss", "εγρήγορση": "εγρήγορση — alertness", "να αντέξω": "αντέχω — to hold out, keep going", "κρεβατοκάμαρας": "κρεβατοκάμαρα — bedroom", "εξετάσεις": "εξετάσεις — (medical) tests"},
})

ITEMS.append({
 "id": "l7-dia-kinito", "title": "Στο κατάστημα κινητής τηλεφωνίας", "title_en": "At the mobile phone shop", "type": "dialogue", "level": "B2",
 "context_el": "Θα ακούσετε έναν πελάτη, τον Γιάννη, να συζητά με μια υπάλληλο σε ένα κατάστημα κινητής τηλεφωνίας.",
 "script": [
  L("Υπάλληλος", "f", "Καλησπέρα, πώς μπορώ να σας βοηθήσω;", "Good afternoon, how can I help you?"),
  L("Γιάννης", "m", "Καλησπέρα. Το συμβόλαιό μου λήγει τον άλλο μήνα και πληρώνω τριάντα πέντε ευρώ για ένα πρόγραμμα που δεν το χρησιμοποιώ ολόκληρο. Μιλάω ελάχιστα, αλλά χρειάζομαι πολλά δεδομένα, γιατί δουλεύω συχνά εκτός γραφείου.", "Good afternoon. My contract runs out next month and I pay thirty-five euros for a plan I don't use in full. I talk very little, but I need a lot of data, because I often work out of the office."),
  L("Υπάλληλος", "f", "Κατάλαβα. Έχουμε ένα πρόγραμμα με απεριόριστα δεδομένα και τριακόσια λεπτά ομιλίας, στα είκοσι εννιά ευρώ τον μήνα, με δέσμευση δύο χρόνων. Ή το ίδιο χωρίς δέσμευση, στα τριάντα δύο.", "I see. We have a plan with unlimited data and three hundred minutes of calls, at twenty-nine euros a month, with a two-year commitment. Or the same without a commitment, at thirty-two."),
  L("Γιάννης", "m", "Και αν πάρω και καινούργια συσκευή;", "And if I take a new handset as well?"),
  L("Υπάλληλος", "f", "Τότε η συσκευή εξοφλείται σε δόσεις μαζί με τον λογαριασμό, και η δέσμευση είναι υποχρεωτική. Αν διακόψετε νωρίτερα, πληρώνετε τις δόσεις που απομένουν.", "Then the handset is paid off in instalments together with the bill, and the commitment is compulsory. If you cancel earlier, you pay the remaining instalments."),
  L("Γιάννης", "m", "Το κινητό μου δουλεύει μια χαρά, δεν χρειάζομαι καινούργιο. Θα προτιμήσω το πρόγραμμα χωρίς δέσμευση. Τρία ευρώ παραπάνω, αλλά είμαι ελεύθερος να φύγω όποτε θέλω.", "My phone works perfectly well, I don't need a new one. I'll go for the plan without a commitment. Three euros more, but I'm free to leave whenever I want."),
 ],
 "questions": [
  Q("Γιατί θέλει ο Γιάννης να αλλάξει πρόγραμμα;", ["Γιατί μιλάει πολύ και του τελειώνουν τα λεπτά", "Γιατί πληρώνει για πράγματα που δεν χρησιμοποιεί και θέλει περισσότερα δεδομένα", "Γιατί χάλασε το κινητό του", "Γιατί μετακομίζει στο εξωτερικό"], 1, "πληρώνω τριάντα πέντε ευρώ για ένα πρόγραμμα που δεν το χρησιμοποιώ ολόκληρο. Μιλάω ελάχιστα, αλλά χρειάζομαι πολλά δεδομένα"),
  Q("Ποια είναι η διαφορά ανάμεσα στις δύο προσφορές;", ["Η μία έχει απεριόριστα λεπτά", "Η φθηνότερη απαιτεί δέσμευση δύο χρόνων", "Η ακριβότερη περιλαμβάνει κινητό", "Η μία ισχύει μόνο για το εξωτερικό"], 1, "στα είκοσι εννιά ευρώ τον μήνα, με δέσμευση δύο χρόνων. Ή το ίδιο χωρίς δέσμευση, στα τριάντα δύο"),
  Q("Τι γίνεται αν κάποιος πάρει συσκευή και διακόψει νωρίτερα;", ["Τίποτα, μπορεί να φύγει ελεύθερα", "Πρέπει να επιστρέψει τη συσκευή", "Πληρώνει τις δόσεις που απομένουν", "Πληρώνει πρόστιμο ενός μηνός"], 2, "Αν διακόψετε νωρίτερα, πληρώνετε τις δόσεις που απομένουν."),
  Q("Τι επιλέγει τελικά ο Γιάννης και γιατί;", ["Το φθηνότερο πρόγραμμα, για να εξοικονομήσει χρήματα", "Πρόγραμμα με νέο κινητό, γιατί το δικό του είναι παλιό", "Το πρόγραμμα χωρίς δέσμευση, για να μπορεί να φύγει όποτε θέλει", "Κανένα, θα το σκεφτεί"], 2, "Θα προτιμήσω το πρόγραμμα χωρίς δέσμευση ... είμαι ελεύθερος να φύγω όποτε θέλω"),
 ],
 "gloss": {"κινητής τηλεφωνίας": "κινητή τηλεφωνία — mobile telephony", "δεδομένα": "δεδομένα — (mobile) data", "απεριόριστα": "απεριόριστος — unlimited", "δέσμευση": "δέσμευση — commitment, lock-in period", "συσκευή": "συσκευή — device, handset", "εξοφλείται": "εξοφλούμαι — to be paid off", "δόσεις": "δόση — instalment", "διακόψετε": "διακόπτω — to discontinue, cancel", "μια χαρά": "μια χαρά — perfectly well"},
})

ITEMS.append({
 "id": "l7-int-daskala", "title": "Δασκάλα σε ένα μικρό νησί", "title_en": "A teacher on a small island", "type": "interview", "level": "B2",
 "context_el": "Θα ακούσετε μια συνέντευξη με τη Μαρίνα, δασκάλα σε ένα μονοθέσιο δημοτικό σχολείο σε ένα μικρό νησί του Αιγαίου.",
 "script": [
  L("Δημοσιογράφος", "m", "Μαρίνα, πόσους μαθητές έχει φέτος το σχολείο σου;", "Marina, how many pupils does your school have this year?"),
  L("Μαρίνα", "f", "Επτά. Από την πρώτη μέχρι την έκτη τάξη, όλοι στην ίδια αίθουσα, με μία δασκάλα, εμένα. Στην αρχή με τρόμαζε. Πώς να διδάξεις ταυτόχρονα το αλφάβητο σε ένα εξάχρονο και κλάσματα σε ένα δωδεκάχρονο;", "Seven. From the first to the sixth year, all in the same classroom, with one teacher, me. At first it scared me. How do you teach the alphabet to a six-year-old and fractions to a twelve-year-old at the same time?"),
  L("Δημοσιογράφος", "m", "Και πώς το κάνεις;", "And how do you do it?"),
  L("Μαρίνα", "f", "Ανακάλυψα ότι τα παιδιά μαθαίνουν πολύ το ένα από το άλλο. Οι μεγάλοι βοηθούν τους μικρούς στην ανάγνωση, κι έτσι επαναλαμβάνουν κι εκείνοι. Κάνουμε επίσης πολλά μαθήματα έξω: φυσική στην ακτή, ιστορία στο κάστρο του νησιού.", "I discovered that children learn a lot from one another. The older ones help the little ones with reading, and that way they revise too. We also have many lessons outside: science on the shore, history at the island's castle."),
  L("Δημοσιογράφος", "m", "Τι σου λείπει;", "What do you miss?"),
  L("Μαρίνα", "f", "Τον χειμώνα, όταν το πλοίο δεν πιάνει λιμάνι για μέρες λόγω καιρού, νιώθω απομονωμένη. Δεν υπάρχει κινηματογράφος, ούτε βιβλιοπωλείο. Αλλά οι γονείς με αντιμετωπίζουν σαν μέλος της οικογένειας. Μου φέρνουν ψάρια, αυγά, γλυκά. Και ξέρω ότι, αν κλείσει αυτό το σχολείο, θα φύγουν και οι οικογένειες. Αυτό μου δίνει δύναμη.", "In winter, when the ferry can't call at the harbour for days because of the weather, I feel isolated. There's no cinema, no bookshop. But the parents treat me like a member of the family. They bring me fish, eggs, sweets. And I know that if this school closes, the families will leave too. That gives me strength."),
 ],
 "questions": [
  Q("Τι ιδιαίτερο έχει το σχολείο της Μαρίνας;", ["Έχει μόνο μαθητές της έκτης τάξης", "Όλοι οι μαθητές, από την πρώτη ως την έκτη, κάνουν μάθημα μαζί με μία δασκάλα", "Λειτουργεί μόνο το καλοκαίρι", "Τα μαθήματα γίνονται μέσω ίντερνετ"], 1, "Από την πρώτη μέχρι την έκτη τάξη, όλοι στην ίδια αίθουσα, με μία δασκάλα"),
  Q("Ποια λύση βρήκε για τη διδασκαλία;", ["Χωρίζει τα παιδιά σε δύο βάρδιες", "Ζήτησε δεύτερη δασκάλα", "Οι μεγαλύτεροι μαθητές βοηθούν τους μικρότερους", "Δίνει περισσότερες εργασίες για το σπίτι"], 2, "Οι μεγάλοι βοηθούν τους μικρούς στην ανάγνωση"),
  Q("Πότε νιώθει απομονωμένη;", ["Όταν ο κακός καιρός σταματά τα πλοία", "Το καλοκαίρι, όταν έρχονται τουρίστες", "Όταν οι γονείς δεν της μιλούν", "Τα Σαββατοκύριακα"], 0, "όταν το πλοίο δεν πιάνει λιμάνι για μέρες λόγω καιρού, νιώθω απομονωμένη"),
  Q("Γιατί πιστεύει ότι η δουλειά της είναι σημαντική για το νησί;", ["Γιατί χωρίς σχολείο οι οικογένειες θα έφευγαν από το νησί", "Γιατί είναι η μόνη δασκάλα στην Ελλάδα σε τέτοιο σχολείο", "Γιατί φέρνει τουρισμό", "Γιατί διδάσκει και τους ενήλικες"], 0, "αν κλείσει αυτό το σχολείο, θα φύγουν και οι οικογένειες"),
 ],
 "gloss": {"μονοθέσιο": "μονοθέσιο σχολείο — one-teacher school", "με τρόμαζε": "τρομάζω — to frighten; to be frightened", "ταυτόχρονα": "ταυτόχρονα — at the same time", "κλάσματα": "κλάσμα — fraction", "ανάγνωση": "ανάγνωση — reading", "επαναλαμβάνουν": "επαναλαμβάνω — to repeat, revise", "ακτή": "ακτή — shore", "πιάνει λιμάνι": "πιάνω λιμάνι — to call at a port", "απομονωμένη": "απομονωμένος — isolated", "με αντιμετωπίζουν": "αντιμετωπίζω — to treat, deal with"},
})

ITEMS.append({
 "id": "l7-rep-kafsonas", "title": "Μέτρα για τον καύσωνα", "title_en": "Measures for the heatwave", "type": "report", "level": "B2",
 "context_el": "Θα ακούσετε ένα ρεπορτάζ από δελτίο ειδήσεων για τα μέτρα ενός δήμου ενόψει καύσωνα.",
 "script": [
  L("Ρεπόρτερ", "m", "Με θερμοκρασίες που αναμένεται να φτάσουν τους σαράντα τρεις βαθμούς από αύριο, ο δήμος ανακοίνωσε έκτακτα μέτρα για την προστασία των πολιτών.", "With temperatures expected to reach forty-three degrees from tomorrow, the municipality has announced emergency measures to protect citizens."),
  L("Ρεπόρτερ", "m", "Τρεις κλιματιζόμενες αίθουσες, στο δημαρχείο, στη δημοτική βιβλιοθήκη και στο κέντρο νεότητας, θα λειτουργούν από τις δέκα το πρωί μέχρι τις οκτώ το βράδυ. Εκεί θα υπάρχει νερό και θα βρίσκεται νοσηλευτής.", "Three air-conditioned halls, at the town hall, the municipal library and the youth centre, will be open from ten in the morning until eight in the evening. There will be water there and a nurse will be present."),
  L("Ρεπόρτερ", "m", "Οι υπάλληλοι του δήμου που εργάζονται σε εξωτερικούς χώρους θα σταματούν τη δουλειά από τις δώδεκα έως τις πέντε. Παράλληλα, εθελοντές θα τηλεφωνούν καθημερινά σε ηλικιωμένους που μένουν μόνοι τους.", "Municipal employees who work outdoors will stop work from twelve until five. At the same time, volunteers will phone elderly people who live alone every day."),
  L("Ρεπόρτερ", "m", "Οι γιατροί συστήνουν να αποφεύγουμε την έκθεση στον ήλιο τις μεσημεριανές ώρες, να πίνουμε νερό ακόμα κι αν δεν διψάμε, και να μην αφήνουμε ποτέ παιδιά ή κατοικίδια μέσα σε σταθμευμένο αυτοκίνητο.", "Doctors advise us to avoid exposure to the sun at midday, to drink water even if we're not thirsty, and never to leave children or pets in a parked car."),
 ],
 "questions": [
  Q("Τι θα βρουν οι πολίτες στις κλιματιζόμενες αίθουσες;", ["Δωρεάν φαγητό", "Νερό και νοσηλευτή", "Κρεβάτια για τη νύχτα", "Ανεμιστήρες για να πάρουν σπίτι"], 1, "Εκεί θα υπάρχει νερό και θα βρίσκεται νοσηλευτής."),
  Q("Τι αλλάζει για τους υπαλλήλους που δουλεύουν έξω;", ["Θα δουλεύουν μόνο τη νύχτα", "Θα πάρουν επίδομα καύσωνα", "Δεν θα δουλεύουν τις πιο ζεστές ώρες της μέρας", "Θα πάρουν άδεια για μία εβδομάδα"], 2, "θα σταματούν τη δουλειά από τις δώδεκα έως τις πέντε"),
  Q("Πώς θα βοηθηθούν οι ηλικιωμένοι που ζουν μόνοι;", ["Θα μεταφερθούν σε ξενοδοχεία", "Εθελοντές θα τους τηλεφωνούν κάθε μέρα", "Θα τους δοθούν κλιματιστικά", "Γιατρός θα τους επισκέπτεται"], 1, "εθελοντές θα τηλεφωνούν καθημερινά σε ηλικιωμένους που μένουν μόνοι τους"),
  Q("Ποια συμβουλή ΔΕΝ δίνουν οι γιατροί;", ["Να πίνουμε νερό χωρίς να περιμένουμε να διψάσουμε", "Να μην αφήνουμε παιδιά σε σταθμευμένο αυτοκίνητο", "Να αποφεύγουμε τον ήλιο το μεσημέρι", "Να κάνουμε κρύο ντους κάθε δύο ώρες"], 3, "να αποφεύγουμε την έκθεση στον ήλιο ... να πίνουμε νερό ... να μην αφήνουμε ποτέ παιδιά"),
 ],
 "gloss": {"καύσωνα": "καύσωνας — heatwave", "έκτακτα": "έκτακτος — emergency, extraordinary", "κλιματιζόμενες": "κλιματιζόμενος — air-conditioned", "δημαρχείο": "δημαρχείο — town hall", "νοσηλευτής": "νοσηλευτής — nurse", "εξωτερικούς χώρους": "εξωτερικός χώρος — outdoor area", "έκθεση": "έκθεση (στον ήλιο) — exposure (to the sun)", "κατοικίδια": "κατοικίδιο — pet", "σταθμευμένο": "σταθμευμένος — parked"},
})

ITEMS.append({
 "id": "l7-mon-mathainontas", "title": "Μαθαίνοντας ελληνικά στα σαράντα", "title_en": "Learning Greek at forty", "type": "monologue", "level": "B2",
 "context_el": "Θα ακούσετε τον Τόμας, έναν Ολλανδό που ζει στην Κρήτη, να μιλάει σε ένα podcast για το πώς έμαθε ελληνικά.",
 "script": [
  L("Τόμας", "m", "Όταν ήρθα στην Κρήτη, πριν από οκτώ χρόνια, ήξερα να πω μόνο «καλημέρα» και «ευχαριστώ». Νόμιζα ότι με τα αγγλικά θα τα έβγαζα πέρα. Και για τα βασικά, πράγματι, τα έβγαζα. Αλλά ένιωθα πάντα ξένος.", "When I came to Crete eight years ago, I could only say 'good morning' and 'thank you'. I thought I'd get by with English. And for the basics, I did. But I always felt like an outsider."),
  L("Τόμας", "m", "Το σημείο που άλλαξαν όλα ήταν ένα τραπέζι, σε έναν γάμο στο χωριό. Όλοι γελούσαν με τα αστεία του κουμπάρου κι εγώ χαμογελούσα σαν χαζός, χωρίς να καταλαβαίνω τίποτα. Εκείνο το βράδυ αποφάσισα να μάθω τη γλώσσα σοβαρά.", "The moment when everything changed was a table at a wedding in the village. Everyone was laughing at the best man's jokes and I was smiling like a fool without understanding anything. That evening I decided to learn the language seriously."),
  L("Τόμας", "m", "Η γραμματική με τρέλανε. Τρία γένη, τέσσερις πτώσεις, ρήματα με δύο θέματα. Στην αρχή έλεγα «η τραπέζι» και «ο θάλασσα», και οι γείτονες με διόρθωναν με απίστευτη υπομονή.", "The grammar drove me mad. Three genders, four cases, verbs with two stems. At first I said 'η τραπέζι' and 'ο θάλασσα', and the neighbours corrected me with incredible patience."),
  L("Τόμας", "m", "Αυτό που με βοήθησε περισσότερο δεν ήταν τα βιβλία, αλλά το καφενείο. Κάθε πρωί έπινα τον καφέ μου με τους ηλικιωμένους του χωριού και τους άκουγα να μαλώνουν για την πολιτική και το ποδόσφαιρο. Σήμερα μαλώνω κι εγώ μαζί τους, στα ελληνικά. Και, το καλύτερο απ' όλα, καταλαβαίνω τα αστεία.", "What helped me most wasn't books but the kafeneio. Every morning I drank my coffee with the old men of the village and listened to them arguing about politics and football. Today I argue with them too, in Greek. And, best of all, I understand the jokes."),
 ],
 "questions": [
  Q("Πώς ένιωθε ο Τόμας τα πρώτα χρόνια στην Κρήτη;", ["Δεν μπορούσε να εξυπηρετηθεί πουθενά", "Τα κατάφερνε με τα αγγλικά, αλλά ένιωθε ξένος", "Είχε πολλούς Έλληνες φίλους", "Ήθελε να γυρίσει στην Ολλανδία"], 1, "για τα βασικά, πράγματι, τα έβγαζα. Αλλά ένιωθα πάντα ξένος"),
  Q("Τι τον έκανε να αποφασίσει να μάθει ελληνικά σοβαρά;", ["Μια δουλειά που του πρότειναν", "Ένα γεγονός σε γάμο, όπου δεν καταλάβαινε τα αστεία", "Μια εξέταση για την ιθαγένεια", "Η γυναίκα του"], 1, "Όλοι γελούσαν με τα αστεία του κουμπάρου κι εγώ χαμογελούσα σαν χαζός"),
  Q("Ποια λάθη έκανε στην αρχή;", ["Μπέρδευε τα γένη των ουσιαστικών", "Μιλούσε πολύ γρήγορα", "Χρησιμοποιούσε κρητικές λέξεις", "Έγραφε χωρίς τόνους"], 0, "έλεγα «η τραπέζι» και «ο θάλασσα»"),
  Q("Τι τον βοήθησε περισσότερο;", ["Ένα μάθημα στο πανεπιστήμιο", "Οι εφαρμογές στο κινητό", "Οι καθημερινές συζητήσεις στο καφενείο", "Τα βιβλία γραμματικής"], 2, "Αυτό που με βοήθησε περισσότερο δεν ήταν τα βιβλία, αλλά το καφενείο."),
 ],
 "gloss": {"θα τα έβγαζα πέρα": "τα βγάζω πέρα — to get by, manage", "κουμπάρου": "κουμπάρος — best man; godparent", "σαν χαζός": "σαν χαζός — like a fool", "με τρέλανε": "τρελαίνω — to drive mad", "γένη": "γένος — (grammatical) gender", "πτώσεις": "πτώση — (grammatical) case", "θέματα": "θέμα — (verb) stem", "υπομονή": "υπομονή — patience", "καφενείο": "καφενείο — traditional coffee house", "να μαλώνουν": "μαλώνω — to argue, quarrel"},
})

ITEMS.append({
 "id": "l7-int-mageiras", "title": "Ένας σεφ ενάντια στη σπατάλη", "title_en": "A chef against food waste", "type": "interview", "level": "B2",
 "context_el": "Θα ακούσετε μια συνέντευξη με τον Φώτη, σεφ και ιδιοκτήτη μιας ταβέρνας στον Πειραιά, για το πώς μείωσε τη σπατάλη τροφίμων.",
 "script": [
  L("Δημοσιογράφος", "f", "Φώτη, λένε ότι στην ταβέρνα σου δεν πετιέται σχεδόν τίποτα. Πώς γίνεται αυτό;", "Fotis, they say that almost nothing is thrown away in your taverna. How is that possible?"),
  L("Φώτης", "m", "Δεν έγινε από τη μια μέρα στην άλλη. Πριν από τρία χρόνια ζύγισα για έναν μήνα ό,τι πετούσαμε. Ήταν πάνω από τριακόσια κιλά. Ντράπηκα. Από τότε άλλαξα τον τρόπο που δουλεύουμε.", "It didn't happen overnight. Three years ago I weighed everything we threw away for a month. It was over three hundred kilos. I was ashamed. Since then I've changed the way we work."),
  L("Δημοσιογράφος", "f", "Τι άλλαξες συγκεκριμένα;", "What exactly did you change?"),
  L("Φώτης", "m", "Πρώτα, μίκρυνα τον κατάλογο. Είχαμε σαράντα πιάτα· τώρα έχουμε δεκαπέντε, που αλλάζουν ανάλογα με την εποχή και με το τι φέρνουν οι ψαράδες. Δεύτερον, ό,τι περισσεύει το μεσημέρι γίνεται κάτι άλλο το βράδυ: το ψωμί γίνεται παξιμάδι, τα λαχανικά σούπα.", "First, I shortened the menu. We had forty dishes; now we have fifteen, which change according to the season and what the fishermen bring. Second, whatever is left over at lunchtime becomes something else in the evening: the bread becomes rusks, the vegetables soup."),
  L("Φώτης", "m", "Και τρίτον, οι μερίδες. Οι Έλληνες έχουμε μάθει ότι η φιλοξενία σημαίνει τραπέζι που ξεχειλίζει. Τώρα ρωτάμε τους πελάτες πόσο πεινάνε και προσφέρουμε και μισές μερίδες. Στην αρχή κάποιοι παραξενεύτηκαν. Σήμερα πολλοί μάς ευχαριστούν.", "And third, the portions. We Greeks have learned that hospitality means a table that overflows. Now we ask customers how hungry they are and we also offer half portions. At first some people found it odd. Today many thank us."),
  L("Δημοσιογράφος", "f", "Και οικονομικά;", "And financially?"),
  L("Φώτης", "m", "Γλιτώνω σχεδόν το ένα πέμπτο από το κόστος των πρώτων υλών. Οπότε όχι, η οικολογία δεν είναι πολυτέλεια. Είναι και καλή επιχείρηση.", "I save almost a fifth of the cost of raw ingredients. So no, ecology isn't a luxury. It's good business too."),
 ],
 "questions": [
  Q("Τι έκανε τον Φώτη να αλλάξει τρόπο δουλειάς;", ["Ένα πρόστιμο από τον δήμο", "Η διαπίστωση, μετά από ζύγισμα, ότι πετούσαν πολύ φαγητό", "Παράπονα από πελάτες", "Ένα σεμινάριο στο εξωτερικό"], 1, "ζύγισα για έναν μήνα ό,τι πετούσαμε. Ήταν πάνω από τριακόσια κιλά. Ντράπηκα."),
  Q("Τι έκανε με τον κατάλογο;", ["Τον μεγάλωσε, για να έχει περισσότερη ποικιλία", "Τον έκανε μικρότερο και εποχικό", "Έβγαλε όλα τα ψάρια", "Τον μετέφρασε σε πολλές γλώσσες"], 1, "μίκρυνα τον κατάλογο ... δεκαπέντε, που αλλάζουν ανάλογα με την εποχή"),
  Q("Πώς αντέδρασαν οι πελάτες στις μισές μερίδες;", ["Αρνήθηκαν να τις παραγγείλουν", "Στην αρχή τους φάνηκε περίεργο, αλλά τώρα πολλοί τις εκτιμούν", "Ζήτησαν χαμηλότερες τιμές", "Δεν τις πρόσεξαν"], 1, "Στην αρχή κάποιοι παραξενεύτηκαν. Σήμερα πολλοί μάς ευχαριστούν."),
  Q("Ποιο είναι το συμπέρασμά του;", ["Ότι η μείωση της σπατάλης κοστίζει ακριβά", "Ότι μόνο τα ακριβά εστιατόρια μπορούν να το κάνουν", "Ότι η μείωση της σπατάλης ωφελεί και οικονομικά", "Ότι οι Έλληνες δεν θα αλλάξουν ποτέ συνήθειες"], 2, "Γλιτώνω σχεδόν το ένα πέμπτο ... η οικολογία δεν είναι πολυτέλεια. Είναι και καλή επιχείρηση."),
 ],
 "gloss": {"σπατάλη": "σπατάλη — waste", "πετιέται": "πετιέμαι — to be thrown away", "ζύγισα": "ζυγίζω — to weigh", "Ντράπηκα": "ντρέπομαι — to be ashamed", "μίκρυνα": "μικραίνω — to make smaller, shorten", "περισσεύει": "περισσεύω — to be left over", "παξιμάδι": "παξιμάδι — rusk", "μερίδες": "μερίδα — portion", "ξεχειλίζει": "ξεχειλίζω — to overflow", "παραξενεύτηκαν": "παραξενεύομαι — to find odd, be puzzled", "πρώτων υλών": "πρώτες ύλες — raw materials, ingredients"},
})

ITEMS.append({
 "id": "l7-dia-diakopes", "title": "Νησί ή βουνό;", "title_en": "Island or mountains?", "type": "dialogue", "level": "B2",
 "context_el": "Θα ακούσετε ένα ζευγάρι, τη Χαρά και τον Πέτρο, να συζητούν πού θα πάνε διακοπές τον Αύγουστο.",
 "script": [
  L("Χαρά", "f", "Πέτρο, πρέπει να κλείσουμε κάτι για τον Αύγουστο, αλλιώς δεν θα βρούμε τίποτα. Σκεφτόμουν τη Νάξο. Έχει παραλίες για τα παιδιά, καλό φαγητό, και το πλοίο δεν είναι πολύ ακριβό.", "Petros, we need to book something for August, otherwise we won't find anything. I was thinking of Naxos. It has beaches for the children, good food, and the ferry isn't too expensive."),
  L("Πέτρος", "m", "Τη Νάξο τον Δεκαπενταύγουστο; Θα είναι τίγκα στον κόσμο. Πέρσι στην Πάρο περιμέναμε σαράντα λεπτά για ένα τραπέζι. Λέω να πάμε φέτος κάπου διαφορετικά: στα Ζαγοροχώρια. Δροσιά, πεζοπορία, ησυχία.", "Naxos around the Fifteenth of August? It'll be packed. Last year on Paros we waited forty minutes for a table. I suggest we go somewhere different this year: the Zagori villages. Cool air, hiking, peace and quiet."),
  L("Χαρά", "f", "Τα παιδιά θα βαρεθούν θανάσιμα. Ο Αλέξης ζει για τη θάλασσα. Και εγώ δουλεύω όλο τον χρόνο, θέλω να κολυμπήσω, όχι να ανεβαίνω βουνά.", "The kids will be bored to death. Alexis lives for the sea. And I work all year round, I want to swim, not climb mountains."),
  L("Πέτρος", "m", "Εντάξει, δίκιο έχεις για τον Αλέξη. Τι λες για έναν συμβιβασμό; Μια εβδομάδα στο βουνό στα τέλη Ιουλίου, πριν ζεστάνει πολύ, και μια εβδομάδα σε νησί στα μέσα Σεπτεμβρίου, που φεύγει ο κόσμος και τα δωμάτια είναι φθηνότερα.", "All right, you're right about Alexis. What about a compromise? A week in the mountains at the end of July, before it gets too hot, and a week on an island in mid-September, when the crowds leave and the rooms are cheaper."),
  L("Χαρά", "f", "Τον Σεπτέμβριο ανοίγουν τα σχολεία, Πέτρο. Στις έντεκα χτυπάει το κουδούνι.", "Schools open in September, Petros. The bell rings on the eleventh."),
  L("Πέτρος", "m", "Σωστά, το ξέχασα. Τότε το νησί στις αρχές Σεπτεμβρίου, από την πρώτη ως την όγδοη. Και κάποιο λιγότερο γνωστό, όχι Νάξο. Τι λες για την Αμοργό;", "Right, I forgot. Then the island at the start of September, from the first to the eighth. And somewhere less well known, not Naxos. What do you say to Amorgos?"),
 ],
 "questions": [
  Q("Γιατί ο Πέτρος δεν θέλει να πάνε στη Νάξο τον Αύγουστο;", ["Γιατί το πλοίο είναι πολύ ακριβό", "Γιατί θα έχει πάρα πολύ κόσμο", "Γιατί έχουν ξαναπάει", "Γιατί δεν έχει καλές παραλίες"], 1, "Θα είναι τίγκα στον κόσμο."),
  Q("Γιατί η Χαρά δεν θέλει το βουνό;", ["Γιατί τα παιδιά και η ίδια θέλουν θάλασσα", "Γιατί φοβάται την πεζοπορία", "Γιατί είναι πολύ μακριά", "Γιατί κάνει κρύο"], 0, "Ο Αλέξης ζει για τη θάλασσα. Και εγώ ... θέλω να κολυμπήσω"),
  Q("Γιατί δεν μπορούν να πάνε στο νησί στα μέσα Σεπτεμβρίου;", ["Γιατί κλείνουν τα ξενοδοχεία", "Γιατί η Χαρά πιάνει δουλειά", "Γιατί ανοίγουν τα σχολεία", "Γιατί σταματούν τα πλοία"], 2, "Τον Σεπτέμβριο ανοίγουν τα σχολεία ... Στις έντεκα χτυπάει το κουδούνι."),
  Q("Σε ποιο σχέδιο καταλήγουν περίπου;", ["Δύο εβδομάδες στη Νάξο τον Αύγουστο", "Μόνο βουνό τον Ιούλιο", "Βουνό στα τέλη Ιουλίου και ένα λιγότερο γνωστό νησί στις αρχές Σεπτεμβρίου", "Να μείνουν φέτος στο σπίτι"], 2, "Μια εβδομάδα στο βουνό στα τέλη Ιουλίου ... Τότε το νησί στις αρχές Σεπτεμβρίου ... Τι λες για την Αμοργό;"),
 ],
 "gloss": {"να κλείσουμε": "κλείνω — to book", "Δεκαπενταύγουστο": "Δεκαπενταύγουστος — 15 August (Dormition holiday)", "τίγκα": "τίγκα — (colloquial) packed, crammed", "πεζοπορία": "πεζοπορία — hiking", "θα βαρεθούν θανάσιμα": "βαριέμαι θανάσιμα — to be bored to death", "συμβιβασμό": "συμβιβασμός — compromise", "ζεστάνει": "ζεσταίνει — it gets hot", "χτυπάει το κουδούνι": "χτυπάει το κουδούνι — the (school) bell rings"},
})

ITEMS.append({
 "id": "l7-rep-vivliothiki", "title": "Η βιβλιοθήκη που δανείζει εργαλεία", "title_en": "The library that lends tools", "type": "report", "level": "B2",
 "context_el": "Θα ακούσετε ένα ρεπορτάζ για μια δημοτική βιβλιοθήκη που άρχισε να δανείζει όχι μόνο βιβλία.",
 "script": [
  L("Ρεπόρτερ", "f", "Στη δημοτική βιβλιοθήκη της πόλης, δίπλα στα ράφια με τα μυθιστορήματα, υπάρχει από φέτος ένα ράφι με δράπανα, σκάλες, σκηνές για κάμπινγκ, ακόμα και ραπτομηχανές. Μπορεί να τα δανειστεί όποιος έχει κάρτα μέλους, για μία εβδομάδα, δωρεάν.", "At the town's municipal library, next to the shelves of novels, there is from this year a shelf with drills, ladders, camping tents, even sewing machines. Anyone with a membership card can borrow them for a week, free of charge."),
  L("Ρεπόρτερ", "f", "Η ιδέα, λέει η διευθύντρια της βιβλιοθήκης, είναι απλή: ένα δράπανο χρησιμοποιείται κατά μέσο όρο λίγα λεπτά σε όλη του τη ζωή. Γιατί να αγοράζει ένα κάθε νοικοκυριό;", "The idea, says the library's director, is simple: a drill is used on average for a few minutes in its whole lifetime. Why should every household buy one?"),
  L("Ρεπόρτερ", "f", "Τα περισσότερα αντικείμενα τα δώρισαν κάτοικοι της πόλης. Ένας συνταξιούχος ηλεκτρολόγος ελέγχει εθελοντικά κάθε συσκευή πριν δανειστεί. Τους πρώτους έξι μήνες έγιναν πάνω από εννιακόσιοι δανεισμοί.", "Most of the items were donated by local residents. A retired electrician volunteers to check every device before it is lent. In the first six months there were over nine hundred loans."),
  L("Ρεπόρτερ", "f", "Το μόνο πρόβλημα, παραδέχεται η διευθύντρια, είναι ότι μερικοί επιστρέφουν τα εργαλεία με καθυστέρηση. Γι' αυτό σκέφτονται να βάλουν ένα μικρό πρόστιμο, όπως ισχύει και για τα βιβλία.", "The only problem, the director admits, is that some people return the tools late. That's why they're thinking of introducing a small fine, as is the case for books."),
 ],
 "questions": [
  Q("Τι καινούργιο προσφέρει η βιβλιοθήκη;", ["Μαθήματα επισκευών", "Δανεισμό εργαλείων και άλλων αντικειμένων", "Πώληση μεταχειρισμένων βιβλίων", "Ένα καφέ για τα μέλη"], 1, "υπάρχει από φέτος ένα ράφι με δράπανα, σκάλες, σκηνές ... Μπορεί να τα δανειστεί όποιος έχει κάρτα μέλους"),
  Q("Ποια είναι η λογική πίσω από την ιδέα;", ["Ότι πολλά εργαλεία χρησιμοποιούνται ελάχιστα και δεν χρειάζεται να τα έχει κάθε σπίτι", "Ότι τα εργαλεία είναι πολύ ακριβά για να τα αγοράσει κανείς", "Ότι η βιβλιοθήκη χρειαζόταν έσοδα", "Ότι οι νέοι δεν διαβάζουν πια βιβλία"], 0, "ένα δράπανο χρησιμοποιείται κατά μέσο όρο λίγα λεπτά σε όλη του τη ζωή. Γιατί να αγοράζει ένα κάθε νοικοκυριό;"),
  Q("Ποιος ελέγχει τις συσκευές;", ["Οι υπάλληλοι της βιβλιοθήκης", "Μια ιδιωτική εταιρεία", "Ένας συνταξιούχος ηλεκτρολόγος, εθελοντικά", "Οι ίδιοι οι δανειζόμενοι"], 2, "Ένας συνταξιούχος ηλεκτρολόγος ελέγχει εθελοντικά κάθε συσκευή"),
  Q("Ποιο πρόβλημα αναφέρει η διευθύντρια;", ["Ότι χάνονται εργαλεία", "Ότι κάποιοι τα επιστρέφουν αργά", "Ότι δεν υπάρχει χώρος", "Ότι λίγοι ενδιαφέρονται"], 1, "μερικοί επιστρέφουν τα εργαλεία με καθυστέρηση"),
 ],
 "gloss": {"ράφια": "ράφι — shelf", "μυθιστορήματα": "μυθιστόρημα — novel", "δράπανα": "δράπανο — drill", "σκηνές": "σκηνή — tent", "ραπτομηχανές": "ραπτομηχανή — sewing machine", "κάρτα μέλους": "κάρτα μέλους — membership card", "κατά μέσο όρο": "κατά μέσο όρο — on average", "δώρισαν": "δωρίζω — to donate", "συνταξιούχος": "συνταξιούχος — pensioner, retired", "δανεισμοί": "δανεισμός — loan, lending", "πρόστιμο": "πρόστιμο — fine"},
})

rnd = random.Random(7)  # spread the right answers over the four positions (the page shows options in file order)
for it in ITEMS:
    for q in it["questions"]: rnd.shuffle(q["options"])
for it in ITEMS:
    for q in it["questions"]: assert q["answer"] in q["options"], (it["id"], q["q"])
    for k in it["gloss"]:
        if not (any(k in s["el"] for s in it["script"]) or k in it["context_el"]): raise SystemExit(f"gloss key not in text: {it['id']} {k}")
root = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
with open(os.path.join(root, "library", "listening", "listening-7.json"), "w", encoding="utf-8") as fh:
    json.dump({"items": ITEMS}, fh, ensure_ascii=False, indent=1); fh.write("\n")
print(len(ITEMS), "items,", sum(len(i["questions"]) for i in ITEMS), "questions")
